def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    # Normalize and discard rows without a usable matching identifier.
    records = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        last_name = normalize_name(row["last_name"])
        if not email and not phone:
            continue

        records.append({
            "index": index,
            "row": row,
            "first_name": normalize_name(row["first_name"]),
            "last_name": last_name,
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": row["source"].strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            ],
        })

    # Union-find provides transitive grouping across email and phone/name matches.
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}
    for i, record in enumerate(records):
        email = record["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone, last_name = record["phone"], record["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def pick(group, field, require_valid=False):
        candidates = [
            record for record in group
            if record[field] and (not require_valid or record[field])
        ]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda record: (
                record["source"] != "manual",
                -record["updated_dt"].timestamp(),
                record["index"],
            ),
        )
        return chosen[field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(r["index"] for r in g)):
        latest = max(record["updated_dt"] for record in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", require_valid=True),
            "phone": pick(group, "phone", require_valid=True),
            "source": pick(group, "source"),
            "tags": ";".join(sorted({tag for record in group for tag in record["tags"]})),
            "opted_out": "Y" if any(record["opted_out"] for record in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
